<?php
declare(strict_types=1);
return static function(PDO $pdo):void{
$pdo->exec("CREATE TABLE IF NOT EXISTS students(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,registration_no VARCHAR(80) NOT NULL,student_name VARCHAR(160) NOT NULL,date_of_admission DATE NOT NULL,discount_in_fee DECIMAL(5,2) NOT NULL DEFAULT 0,mobile VARCHAR(50) NULL,date_of_birth DATE NULL,gender VARCHAR(20) NULL,identification_mark VARCHAR(255) NULL,blood_group VARCHAR(10) NULL,disease VARCHAR(255) NULL,birth_form_nic VARCHAR(100) NULL,caste VARCHAR(100) NULL,previous_school VARCHAR(160) NULL,previous_id_board_roll VARCHAR(100) NULL,additional_note TEXT NULL,orphan_student VARCHAR(10) NULL,osc VARCHAR(10) NULL,religion VARCHAR(50) NULL,family VARCHAR(120) NULL,total_siblings SMALLINT UNSIGNED NULL,address TEXT NULL,father_name VARCHAR(160) NULL,father_education VARCHAR(120) NULL,father_nic VARCHAR(100) NULL,father_mobile VARCHAR(50) NULL,father_occupation VARCHAR(120) NULL,father_profession VARCHAR(120) NULL,father_income DECIMAL(12,2) NULL,mother_name VARCHAR(160) NULL,mother_education VARCHAR(120) NULL,mother_nic VARCHAR(100) NULL,mother_mobile VARCHAR(50) NULL,mother_occupation VARCHAR(120) NULL,mother_profession VARCHAR(120) NULL,mother_income DECIMAL(12,2) NULL,picture_path VARCHAR(255) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_students_registration(institute_id,registration_no),INDEX idx_students_class(class_id),INDEX idx_students_name(student_name),CONSTRAINT fk_students_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_students_class FOREIGN KEY(class_id) REFERENCES classes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS employees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,employee_no VARCHAR(80) NOT NULL,name VARCHAR(160) NOT NULL,picture_path VARCHAR(255) NULL,mobile VARCHAR(50) NULL,joining_date DATE NOT NULL,role ENUM('Principal','Management Staff','Teacher','Accountant','Store Manager','Other') NOT NULL,monthly_salary DECIMAL(12,2) NOT NULL DEFAULT 0,show_on_profile TINYINT(1) NOT NULL DEFAULT 0,father_husband_name VARCHAR(160) NULL,national_id VARCHAR(100) NULL,education VARCHAR(160) NULL,gender VARCHAR(20) NULL,religion VARCHAR(50) NULL,blood_group VARCHAR(10) NULL,experience VARCHAR(255) NULL,email VARCHAR(190) NULL,date_of_birth DATE NULL,home_address TEXT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_employee_no(institute_id,employee_no),INDEX idx_employees_status(status),INDEX idx_employees_name(name),CONSTRAINT fk_employees_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS student_attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status ENUM('Present','Absent','Leave') NOT NULL,remarks VARCHAR(255) NULL,marked_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_student_attendance(student_id,attendance_date),INDEX idx_student_attendance_date(attendance_date),CONSTRAINT fk_student_attendance_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,CONSTRAINT fk_student_attendance_user FOREIGN KEY(marked_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS employee_attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status ENUM('Present','Absent','Leave','Late','Half Day') NOT NULL,time_in TIME NULL,time_out TIME NULL,remarks VARCHAR(255) NULL,marked_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_employee_attendance(employee_id,attendance_date),INDEX idx_employee_attendance_date(attendance_date),CONSTRAINT fk_employee_attendance_employee FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE,CONSTRAINT fk_employee_attendance_user FOREIGN KEY(marked_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS account_heads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,type ENUM('income','expense','both') NOT NULL DEFAULT 'both',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_account_head(institute_id,name),CONSTRAINT fk_account_heads_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS account_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,transaction_date DATE NOT NULL,description VARCHAR(255) NOT NULL,amount DECIMAL(12,2) NOT NULL,transaction_type ENUM('income','expense') NOT NULL,account_head_id BIGINT UNSIGNED NULL,reference_type VARCHAR(50) NULL,reference_id BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_transactions_date(transaction_date),INDEX idx_transactions_type(transaction_type),CONSTRAINT fk_transactions_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_transactions_head FOREIGN KEY(account_head_id) REFERENCES account_heads(id),CONSTRAINT fk_transactions_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS fee_invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,fee_month CHAR(7) NOT NULL,invoice_no VARCHAR(60) NOT NULL,subtotal DECIMAL(12,2) NOT NULL,discount DECIMAL(12,2) NOT NULL DEFAULT 0,previous_balance DECIMAL(12,2) NOT NULL DEFAULT 0,total_amount DECIMAL(12,2) NOT NULL,paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0,remaining_amount DECIMAL(12,2) NOT NULL,status ENUM('unpaid','partial','paid') NOT NULL DEFAULT 'unpaid',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_invoice_month(student_id,fee_month),UNIQUE KEY uq_invoice_no(invoice_no),INDEX idx_invoice_student(student_id),INDEX idx_invoice_status(status),CONSTRAINT fk_invoices_student FOREIGN KEY(student_id) REFERENCES students(id),CONSTRAINT fk_invoices_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS fee_invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fee_invoice_id BIGINT UNSIGNED NOT NULL,particular VARCHAR(120) NOT NULL,amount DECIMAL(12,2) NOT NULL,created_at DATETIME NOT NULL,CONSTRAINT fk_invoice_items_invoice FOREIGN KEY(fee_invoice_id) REFERENCES fee_invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS fee_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fee_invoice_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,receipt_no VARCHAR(60) NOT NULL,payment_date DATE NOT NULL,amount DECIMAL(12,2) NOT NULL,payment_method VARCHAR(40) NOT NULL,reference VARCHAR(100) NULL,received_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_receipt_no(receipt_no),INDEX idx_payments_invoice(fee_invoice_id),INDEX idx_payments_student(student_id),INDEX idx_payments_date(payment_date),CONSTRAINT fk_payments_invoice FOREIGN KEY(fee_invoice_id) REFERENCES fee_invoices(id),CONSTRAINT fk_payments_student FOREIGN KEY(student_id) REFERENCES students(id),CONSTRAINT fk_payments_user FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$now=date('Y-m-d H:i:s');$pdo->prepare("INSERT IGNORE INTO account_heads(institute_id,name,type,status,created_at,updated_at) SELECT id,'General','both','active',:created,:updated FROM institutes ORDER BY id LIMIT 1")->execute(['created'=>$now,'updated'=>$now]);
};
